DROP TABLE IF EXISTS `master_defect_image`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `master_defect_image` (
  `image_id` int NOT NULL AUTO_INCREMENT,
  `defect_id` int NOT NULL COMMENT '关联不良项ID',
  `image_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '图片访问路径',
  `image_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '重命名后的文件名（不良编码+两位流水码）',
  `sort_order` int DEFAULT '0' COMMENT '排序号',
  `file_hash` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件MD5哈希值，用于去重',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`image_id`),
  KEY `defect_id` (`defect_id`),
  CONSTRAINT `master_defect_image_ibfk_1` FOREIGN KEY (`defect_id`) REFERENCES `master_defect_type` (`defect_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
