--
-- Table structure for table `production_process_material`
--

DROP TABLE IF EXISTS `production_process_material`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `production_process_material` (
  `material_id` int NOT NULL AUTO_INCREMENT,
  `report_order_id` int DEFAULT NULL COMMENT '生产报工单ID',
  `process_id` int DEFAULT NULL COMMENT '工序ID',
  `material_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物料类型',
  `bas_material_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联基础料品表ID',
  `material_batch` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物料批次',
  `package_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '包号',
  `quantity` decimal(12,2) DEFAULT '0.00' COMMENT '数量',
  `label_images` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '标签图片(JSON)',
  `record_time` datetime NOT NULL,
  PRIMARY KEY (`material_id`),
  KEY `report_order_id` (`report_order_id`),
  CONSTRAINT `production_process_material_ibfk_1` FOREIGN KEY (`report_order_id`) REFERENCES `production_report_order` (`report_order_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=193 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

