--
-- Table structure for table `production_report_process`
--

DROP TABLE IF EXISTS `production_report_process`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `production_report_process` (
  `id` int NOT NULL AUTO_INCREMENT,
  `report_order_id` int NOT NULL COMMENT '关联生产报工单ID',
  `process_id` int NOT NULL COMMENT '工序ID',
  `process_code` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工序编码',
  `process_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工序名称',
  `has_material` tinyint DEFAULT '0' COMMENT '是否引入物料：0=否, 1=是',
  `sort_order` int DEFAULT '0' COMMENT '工序顺序',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `must_report` tinyint DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `production_report_process_report_order_id_process_id` (`report_order_id`,`process_id`),
  KEY `production_report_process_report_order_id` (`report_order_id`),
  CONSTRAINT `production_report_process_ibfk_1` FOREIGN KEY (`report_order_id`) REFERENCES `production_report_order` (`report_order_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=452 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

