--
-- Table structure for table `quality_incoming_inspection`
--

DROP TABLE IF EXISTS `quality_incoming_inspection`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quality_incoming_inspection` (
  `inspection_id` int NOT NULL AUTO_INCREMENT COMMENT '来料检验ID',
  `inspection_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检验编号（前缀LL+日期+序号）',
  `supplier_id` int DEFAULT NULL COMMENT '供应商ID',
  `supplier_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商名称（冗余）',
  `supplier_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商编码（冗余）',
  `material_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '料品ID',
  `material_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '料号（冗余）',
  `material_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '料品名称（冗余）',
  `specification` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '规格（冗余）',
  `supplier_batch_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商批次号',
  `internal_batch_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '内部批次号',
  `quantity` decimal(15,4) DEFAULT NULL COMMENT '到货数量',
  `arrival_date` datetime DEFAULT NULL COMMENT '到货日期',
  `receipt_id` int DEFAULT NULL COMMENT '关联采购收货采集表ID',
  `receipt_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '采购收货单号（冗余）',
  `line_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '采购收货单行号（冗余）',
  `receipt_status` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '采购收货单据状态（冗余）',
  `standard_id` int DEFAULT NULL COMMENT '关联检验标准ID',
  `standard_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检验标准名称（冗余）',
  `result` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '总结果：合格/不合格',
  `handle_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理方式',
  `handle_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理原因',
  `trigger_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '手工' COMMENT '触发方式：自动/手工',
  `status` tinyint DEFAULT '0' COMMENT '状态：0=待检, 1=检验中, 2=审核中, 3=已完成, 4=已关闭',
  `inspector_id` int DEFAULT NULL COMMENT '检验人ID',
  `inspector_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检验人姓名（冗余）',
  `reviewer_id` int DEFAULT NULL COMMENT '审核人ID',
  `reviewer_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审核人姓名（冗余）',
  `inspection_time` datetime DEFAULT NULL COMMENT '检验时间',
  `review_time` datetime DEFAULT NULL COMMENT '审核时间',
  `remarks` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`inspection_id`),
  UNIQUE KEY `inspection_no` (`inspection_no`),
  UNIQUE KEY `quality_incoming_inspection_inspection_no` (`inspection_no`),
  KEY `standard_id` (`standard_id`),
  KEY `quality_incoming_inspection_supplier_id` (`supplier_id`),
  KEY `quality_incoming_inspection_material_id` (`material_id`),
  KEY `quality_incoming_inspection_status` (`status`),
  KEY `quality_incoming_inspection_created_at` (`created_at`),
  KEY `idx_ii_receipt_id` (`receipt_id`),
  KEY `idx_ii_receipt_line` (`receipt_no`,`line_no`),
  KEY `quality_incoming_inspection_receipt_id` (`receipt_id`),
  CONSTRAINT `quality_incoming_inspection_ibfk_1` FOREIGN KEY (`standard_id`) REFERENCES `quality_inspection_standard` (`standard_id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=881 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

