--
-- Table structure for table `quality_product_inspection`
--

DROP TABLE IF EXISTS `quality_product_inspection`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quality_product_inspection` (
  `inspection_id` int NOT NULL AUTO_INCREMENT COMMENT '产品检测ID',
  `inspection_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检验编号（按类型两位前缀+日期+序号）',
  `inspection_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检验类型：首件/制程/成品/其它',
  `report_order_id` int NOT NULL COMMENT '关联报工单ID',
  `report_order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '报工单号（冗余）',
  `material_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '料品ID（从报工单带出）',
  `material_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '料号（从报工单带出，冗余）',
  `material_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品名称/料品名称（从报工单带出，冗余）',
  `specification` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '规格（从报工单带出，冗余）',
  `standard_id` int DEFAULT NULL COMMENT '关联检验标准ID',
  `standard_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检验标准名称（冗余）',
  `result` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '总结果：合格/不合格',
  `trigger_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '手工' COMMENT '触发方式：自动/手工',
  `status` tinyint DEFAULT '0' COMMENT '状态：0=待检, 1=检验中, 2=审核中, 3=已完成, 4=已关闭',
  `inspector_id` int DEFAULT NULL COMMENT '检验人ID',
  `inspector_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检验人姓名（冗余）',
  `reviewer_id` int DEFAULT NULL COMMENT '审核人ID',
  `reviewer_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审核人姓名（冗余）',
  `inspection_time` datetime DEFAULT NULL COMMENT '检验时间',
  `review_time` datetime DEFAULT NULL COMMENT '审核时间',
  `remarks` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`inspection_id`),
  UNIQUE KEY `inspection_no` (`inspection_no`),
  UNIQUE KEY `quality_product_inspection_inspection_no` (`inspection_no`),
  KEY `quality_product_inspection_inspection_type` (`inspection_type`),
  KEY `quality_product_inspection_report_order_id` (`report_order_id`),
  KEY `quality_product_inspection_status` (`status`),
  KEY `quality_product_inspection_created_at` (`created_at`),
  CONSTRAINT `quality_product_inspection_ibfk_1` FOREIGN KEY (`report_order_id`) REFERENCES `production_report_order` (`report_order_id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=63 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

