--
-- Table structure for table `quality_product_inspection_item`
--

DROP TABLE IF EXISTS `quality_product_inspection_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quality_product_inspection_item` (
  `item_id` int NOT NULL AUTO_INCREMENT COMMENT '检测项目ID',
  `inspection_id` int NOT NULL COMMENT '关联产品检测主表ID',
  `item_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检测项目名称',
  `standard_value` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目标准值',
  `actual_value` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目检测值',
  `result` tinyint DEFAULT NULL COMMENT '项目判定结果：0=不合格, 1=合格',
  `inspector_id` int DEFAULT NULL COMMENT '项目检测人ID',
  `inspector_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目检测人姓名（冗余）',
  `inspection_time` datetime DEFAULT NULL COMMENT '项目检测时间',
  `sort_order` int DEFAULT '0' COMMENT '排序',
  `remarks` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`item_id`),
  KEY `quality_product_inspection_item_inspection_id` (`inspection_id`),
  KEY `quality_product_inspection_item_result` (`result`),
  CONSTRAINT `quality_product_inspection_item_ibfk_1` FOREIGN KEY (`inspection_id`) REFERENCES `quality_product_inspection` (`inspection_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=526 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

