--
-- Table structure for table `task_energy_meter_data`
--

DROP TABLE IF EXISTS `task_energy_meter_data`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `task_energy_meter_data` (
  `id` int NOT NULL AUTO_INCREMENT,
  `task_setting_id` int DEFAULT NULL COMMENT '关联任务设置ID',
  `reading_date` datetime NOT NULL COMMENT '采集时间',
  `device_addr` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '通讯地址',
  `device_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '电表名称',
  `forward_active_energy` decimal(18,4) DEFAULT NULL COMMENT '正向有功总电能(kWh)',
  `forward_reactive_energy` decimal(18,4) DEFAULT NULL COMMENT '正向无功总电能(kvarh)',
  `reverse_active_energy` decimal(18,4) DEFAULT NULL COMMENT '反向有功总电能(kWh)',
  `reverse_reactive_energy` decimal(18,4) DEFAULT NULL COMMENT '反向无功总电能(kvarh)',
  `raw_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '原始数据片段(调试用)',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `task_energy_meter_data_reading_date_device_addr` (`reading_date`,`device_addr`),
  KEY `task_energy_meter_data_reading_date` (`reading_date`),
  KEY `task_energy_meter_data_device_addr` (`device_addr`),
  KEY `task_energy_meter_data_task_setting_id` (`task_setting_id`)
) ENGINE=InnoDB AUTO_INCREMENT=103370 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

