--
-- Table structure for table `task_env_alarm_record`
--

DROP TABLE IF EXISTS `task_env_alarm_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `task_env_alarm_record` (
  `alarm_id` int NOT NULL AUTO_INCREMENT,
  `factor_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '因子ID',
  `device_addr` int NOT NULL COMMENT '设备地址',
  `device_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备名称',
  `node_id` int NOT NULL COMMENT '节点ID',
  `register_id` int NOT NULL COMMENT '寄存器ID',
  `factor_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '因子名称',
  `alarm_info` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '报警信息',
  `alarm_level` int NOT NULL COMMENT '报警级别',
  `alarm_range` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '报警限值',
  `current_value` double DEFAULT NULL COMMENT '当前报警值',
  `unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位',
  `alarm_time` datetime NOT NULL COMMENT '报警时间',
  `is_handled` tinyint NOT NULL DEFAULT '0' COMMENT '是否已处理：0-未处理 1-已处理',
  `handle_msg` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理意见',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`alarm_id`),
  KEY `task_env_alarm_record_factor_id` (`factor_id`),
  KEY `task_env_alarm_record_device_addr` (`device_addr`),
  KEY `task_env_alarm_record_alarm_time` (`alarm_time`),
  KEY `task_env_alarm_record_alarm_level` (`alarm_level`),
  KEY `task_env_alarm_record_is_handled` (`is_handled`),
  KEY `task_env_alarm_record_factor_id_alarm_time` (`factor_id`,`alarm_time`)
) ENGINE=InnoDB AUTO_INCREMENT=2280 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

