--
-- Table structure for table `task_env_monitor_data`
--

DROP TABLE IF EXISTS `task_env_monitor_data`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `task_env_monitor_data` (
  `monitor_id` int NOT NULL AUTO_INCREMENT,
  `factor_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '因子ID',
  `device_addr` int NOT NULL COMMENT '设备地址',
  `device_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备名称',
  `node_id` int NOT NULL COMMENT '节点ID',
  `register_id` int NOT NULL COMMENT '寄存器ID',
  `factor_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '因子名称',
  `value` double DEFAULT NULL COMMENT '当前值',
  `raw_data` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原始数据',
  `unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位',
  `coefficient` float DEFAULT NULL COMMENT '系数',
  `device_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备状态',
  `collect_time` datetime NOT NULL COMMENT '采集时间(平台时间戳)',
  `data_time` datetime DEFAULT NULL COMMENT '数据时间(系统采集时间)',
