--
-- Table structure for table `task_item`
--

DROP TABLE IF EXISTS `task_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `task_item` (
  `item_id` int NOT NULL AUTO_INCREMENT COMMENT '采集记录ID',
  `task_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源同步任务ID',
  `main_category_code` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '主分类代码（U9来源字段）',
  `category_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分类名称',
  `material_code` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '料号（= 业务主表 material_code）',
  `material_name` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '品名（= 业务主表 material_name）',
  `specification` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '规格',
  `unit_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位名称',
  `film_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '菲林编号',
  `version_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '版本号（对齐 bas_material.version_no）',
