--
-- Table structure for table `task_production_order`
--

DROP TABLE IF EXISTS `task_production_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `task_production_order` (
  `order_id` int NOT NULL AUTO_INCREMENT COMMENT '采集记录ID',
  `task_id` varchar(64) NOT NULL COMMENT '来源同步任务ID',
  `source_type` varchar(100) DEFAULT NULL COMMENT '来源类型',
  `doc_type_name` varchar(100) DEFAULT NULL COMMENT '单据类别名称',
  `biz_create_date` varchar(50) DEFAULT NULL COMMENT '业务制单日期',
  `order_no` varchar(100) NOT NULL COMMENT '单据编号',
  `status` varchar(100) DEFAULT NULL COMMENT '单据状态（开立/开工/完工等）',
  `material_code` varchar(100) DEFAULT NULL COMMENT '料品料号',
  `material_name` varchar(300) DEFAULT NULL COMMENT '料品品名',
  `specification` varchar(500) DEFAULT NULL COMMENT '规格',
  `film_version` varchar(200) DEFAULT NULL COMMENT '菲林编号',
  `version_no` varchar(100) DEFAULT NULL COMMENT '版本',
  `barcode` varchar(100) DEFAULT NULL COMMENT '条形码',
  `planned_qty` decimal(18,4) DEFAULT NULL COMMENT '排产数量',
  `qualified_qty` decimal(18,4) NOT NULL DEFAULT '0.0000' COMMENT '累计合格数量',
  `plan_start_time` varchar(50) DEFAULT NULL COMMENT '计划开工日期',
  `plan_end_time` varchar(50) DEFAULT NULL COMMENT '计划完工日期',
  `created_by` varchar(100) DEFAULT NULL COMMENT '业务制单人',
  `raw_data` text COMMENT '原始数据（JSON）',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`order_id`),
  UNIQUE KEY `uk_task_po_order_no` (`order_no`),
  KEY `idx_task_po_material_code` (`material_code`),
  KEY `idx_task_po_task_id` (`task_id`),
  KEY `idx_task_po_status` (`status`),
  KEY `idx_task_po_biz_date` (`biz_create_date`),
  KEY `idx_task_po_order_no` (`order_no`)
) ENGINE=InnoDB AUTO_INCREMENT=817 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='U9生产订单采集表';
/*!40101 SET character_set_client = @saved_cs_client */;

