--
-- Table structure for table `task_purchase_receipt`
--

DROP TABLE IF EXISTS `task_purchase_receipt`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `task_purchase_receipt` (
  `receipt_id` int NOT NULL AUTO_INCREMENT COMMENT '采集记录ID',
  `task_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源同步任务ID',
  `receipt_no` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '单据编号（r[0]）',
  `material_code` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '料号（r[1]）',
  `material_name` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '料品名称（r[2]）',
  `specification` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '料品规格（r[3]）',
  `business_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务类型（r[4]，如标准采购）',
  `received_qty` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实收数量-采购单位（r[5]）',
  `receive_lot_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '收货批号（r[6]）',
  `supplier_lot_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商批号（r[7]）',
  `source_doc_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源采购订单号（r[8]）',
  `line_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '行号（r[9]）',
  `supplier_code` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商编码（r[10]）',
  `supplier_name` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商名称（r[11]）',
  `status` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单据状态（r[12]，如业务关闭/开立/审核等）',
  `created_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人（r[13]）',
  `receipt_date` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务日期（r[14]）',
  `raw_data` text COLLATE utf8mb4_unicode_ci COMMENT '原始数据（JSON）',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`receipt_id`),
  UNIQUE KEY `uk_task_pr_receipt_line` (`receipt_no`,`line_no`),
  KEY `idx_task_pr_receipt_no` (`receipt_no`),
  KEY `idx_task_pr_material_code` (`material_code`),
  KEY `idx_task_pr_task_id` (`task_id`),
  KEY `idx_task_pr_status` (`status`),
  KEY `idx_task_pr_supplier_code` (`supplier_code`)
) ENGINE=InnoDB AUTO_INCREMENT=2626 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

