--
-- Table structure for table `task_sync_log`
--

DROP TABLE IF EXISTS `task_sync_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `task_sync_log` (
  `task_id` int NOT NULL AUTO_INCREMENT,
  `task_biz_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务任务ID(UUID)',
  `task_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务类型：items/customers/env_monitor/weather',
  `status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT '状态：pending/running/completed/failed',
  `progress` int NOT NULL DEFAULT '0' COMMENT '进度(0-100)',
  `current_step` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '当前步骤说明',
  `steps` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '步骤日志(JSON)',
  `total_records` int DEFAULT NULL COMMENT '总记录数',
  `output_file` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '输出文件路径',
  `output_size` bigint DEFAULT NULL COMMENT '输出文件大小(bytes)',
  `error_msg` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '错误信息',
  `started_at` datetime DEFAULT NULL COMMENT '开始时间',
  `ended_at` datetime DEFAULT NULL COMMENT '结束时间',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`task_id`),
  UNIQUE KEY `task_biz_id` (`task_biz_id`),
  KEY `task_sync_log_task_type_status` (`task_type`,`status`),
  KEY `task_sync_log_created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=5794 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

