--
-- Table structure for table `task_weather_info`
--

DROP TABLE IF EXISTS `task_weather_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `task_weather_info` (
  `weather_id` int NOT NULL AUTO_INCREMENT,
  `city` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '城市/区县名称',
  `temperature` double NOT NULL COMMENT '温度(℃)',
  `humidity` double NOT NULL COMMENT '相对湿度(%)',
  `pressure` double NOT NULL COMMENT '大气压(hPa)',
  `weather_time` datetime NOT NULL COMMENT '气象发布/观测时间',
  `source` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '数据来源站点',
  `raw_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '原始片段(调试用)',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`weather_id`),
  KEY `task_weather_info_city` (`city`),
  KEY `task_weather_info_weather_time` (`weather_time`),
  KEY `task_weather_info_source` (`source`),
  KEY `task_weather_info_city_weather_time` (`city`,`weather_time`)
) ENGINE=InnoDB AUTO_INCREMENT=658 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

